"""Small syntax validators used by the CLI implementation."""
import configparser
import csv
import io
import json
import plistlib
import re
import tomllib
import xml.etree.ElementTree as ET


def _jsonc(s):
    # Remove comments while preserving quoted strings and line positions.
    out=[]; i=0; quote=False; esc=False
    while i<len(s):
        c=s[i]
        if quote:
            out.append(c)
            if esc: esc=False
            elif c=='\\': esc=True
            elif c=='"': quote=False
            i+=1; continue
        if c=='"': quote=True; out.append(c); i+=1; continue
        if s.startswith('//',i):
            while i<len(s) and s[i]!='\n': out.append(' '); i+=1
            continue
        if s.startswith('/*',i):
            out.extend('  '); i+=2
            while i<len(s) and not s.startswith('*/',i):
                out.append('\n' if s[i]=='\n' else ' '); i+=1
            if i<len(s): out.extend('  '); i+=2
            continue
        out.append(c); i+=1
    return ''.join(out)


def _yaml(s):
    # Structural checks for common YAML errors; scalar-heavy files are accepted.
    stack=[]
    for n,line in enumerate(s.splitlines(),1):
        if not line.strip() or line.lstrip().startswith('#') or line.strip() in ('---','...'): continue
        indent=len(line)-len(line.lstrip(' '))
        if '\t' in line[:indent]: return f"line {n}: tabs are not allowed for indentation"
        body=line.strip()
        if body.startswith((':', '- :')): return f"line {n}: could not find expected ':'"
        if body.count('[')!=body.count(']') and not body.startswith('#'): return f"line {n}: flow sequence is not closed"
        if body.count('{')!=body.count('}') and not body.startswith('#'): return f"line {n}: flow mapping is not closed"
        for q in ('"', "'"):
            if body.count(q)%2: return f"line {n}: found unexpected end of stream"
    return None


def validate_content(filetype, text):
    """Return None for valid syntax, otherwise a concise syntax error string."""
    t=filetype.lower().replace('-', '').replace('_','')
    try:
        if t in ('json','sarif'):
            json.loads(text)
        elif t=='jsonc':
            cleaned=_jsonc(text)
            cleaned=re.sub(r',\s*([}\]])',r'\1',cleaned)
            json.loads(cleaned)
        elif t=='toml': tomllib.loads(text)
        elif t in ('xml','plist'):
            if t=='plist': plistlib.loads(text.encode())
            else: ET.fromstring(text)
        elif t in ('ini','properties','editorconfig'):
            cp=configparser.ConfigParser(strict=True, interpolation=None, allow_no_value=True)
            cp.read_string('[__root__]\n'+text if not re.search(r'^\s*\[',text,re.M) else text)
        elif t=='csv':
            list(csv.reader(io.StringIO(text), strict=True))
        elif t=='env':
            for n,line in enumerate(text.splitlines(),1):
                x=line.strip()
                if x and not x.startswith('#') and not re.match(r'(?:export\s+)?[A-Za-z_][A-Za-z0-9_]*\s*=',x):
                    return f'line {n}: invalid environment variable assignment'
        elif t in ('yaml','yml'): return _yaml(text)
        # Formats without stdlib parsers are handled permissively.
        return None
    except json.JSONDecodeError as e:
        return f'line {e.lineno}, column {e.colno}: {e.msg}'
    except tomllib.TOMLDecodeError as e: return str(e)
    except ET.ParseError as e: return str(e)
    except (ValueError, configparser.Error, csv.Error, plistlib.InvalidFileException) as e:
        return str(e)

