"""Output formatting for validation result records.

Records have ``path``, ``status`` (passed/failed), and optional ``errors``.
"""
import html
import json


def _failure(r):
    return r.get("status") in ("failed", "fail", False)


def _record(r):
    o = {"path": r.get("path", ""), "status": "failed" if _failure(r) else "passed"}
    if _failure(r):
        o["errors"] = list(r.get("errors") or [])
    return o


def _group(records, dimensions):
    if not dimensions:
        passed = sum(not _failure(r) for r in records)
        failed = len(records) - passed
        return {"files": [_record(r) for r in records],
                "summary": {"passed": passed, "failed": failed}}
    # Grouped structure follows the validator's nested files/summary shape.
    def key(r, dim):
        if dim == "filetype": return str(r.get("filetype", "unknown")).lower()
        if dim == "directory":
            import os
            return os.path.dirname(r.get("path", "")) or "."
        if dim == "pass-fail": return "Failed" if _failure(r) else "Passed"
        return "syntax" if _failure(r) else "Passed"
    def nest(items, dims, field):
        result = {}
        for r in items:
            k = key(r, dims[0])
            result.setdefault(k, []).append(r)
        for k, vals in list(result.items()):
            if len(dims) > 1:
                result[k] = nest(vals, dims[1:], field)
            elif field == "files":
                result[k] = [_record(r) for r in vals]
            else:
                p = sum(not _failure(r) for r in vals)
                result[k] = [{"passed": p, "failed": len(vals)-p}]
        return result
    p = sum(not _failure(r) for r in records)
    f = len(records)-p
    return {"files": nest(records, dimensions, "files"),
            "summary": nest(records, dimensions, "summary"),
            "totalPassed": p, "totalFailed": f}


def render(records, reporter="standard", groupby=None):
    """Return rendered output for records (without a trailing newline)."""
    records = list(records)
    if not records:
        return ""
    kind = reporter.split(":", 1)[0].lower()
    if kind == "json":
        return json.dumps(_group(records, groupby or []), indent=2, ensure_ascii=False)
    if kind == "standard":
        if groupby:
            def group_key(r, dim):
                if dim == "filetype": return str(r.get("filetype", "unknown")).lower()
                if dim == "directory":
                    import os
                    return os.path.dirname(r.get("path", "")) or "."
                if dim == "pass-fail": return "Failed" if _failure(r) else "Passed"
                if not _failure(r): return "Passed"
                errors = r.get("errors") or []
                return "schema" if any(str(e).startswith("schema:") for e in errors) else "syntax"
            def render_group(items, dims, level=0):
                out = []
                keys = sorted({group_key(r, dims[0]) for r in items})
                for ki, k in enumerate(keys):
                    if ki: out.append("")
                    out.append("    " * level + k)
                    subset = [r for r in items if group_key(r, dims[0]) == k]
                    if len(dims) > 1:
                        out.extend(render_group(subset, dims[1:], level + 1).split("\n"))
                    else:
                        for r in subset:
                            bad = _failure(r)
                            out.append("    " * (level + 1) + f"{'×' if bad else '✓'} {r.get('path', '')}")
                            if bad:
                                out.extend("    " * (level + 2) + f"error: {e}" for e in r.get("errors") or [])
                        if dims[0] in ("filetype", "directory"):
                            passed = sum(not _failure(r) for r in subset)
                            out.extend(["", f"Summary: {passed} succeeded, {len(subset)-passed} failed"])
                return "\n".join(out)
            rendered = render_group(records, groupby)
            if len(groupby) > 1 or groupby[0] not in ("filetype", "directory"):
                passed = sum(not _failure(r) for r in records)
                if rendered: rendered += "\n\n"
                rendered += f"Total Summary: {passed} succeeded, {len(records)-passed} failed"
            return rendered
        lines = []
        for r in records:
            bad = _failure(r)
            lines.append(f"    {'×' if bad else '✓'} {r.get('path', '')}")
            if bad:
                for e in r.get("errors") or []:
                    lines.append(f"        error: {e}")
        return "\n".join(lines)
    if kind == "github":
        import re
        lines = []
        for r in records:
            if not _failure(r): continue
            for e in r.get("errors") or []:
                m = re.search(r"line (\d+), column (\d+):\s*(.*)", str(e))
                pos = f",line={m.group(1)},col={m.group(2)}" if m else ""
                msg = m.group(3) if m else e
                lines.append(f"::error file={r.get('path','')}{pos}::{msg}")
        return "\n".join(lines)
    if kind == "sarif":
        import re
        results = []
        for r in records:
            bad = _failure(r)
            message = (r.get("errors") or ["No errors detected"])[0] if bad else "No errors detected"
            loc = {"physicalLocation": {"artifactLocation": {"uri": "file:///" + str(r.get("path", "")).lstrip("/")}}}
            m = re.search(r"line (\d+), column (\d+):", str(message))
            if m:
                loc["physicalLocation"]["region"] = {"startLine": int(m.group(1)), "startColumn": int(m.group(2))}
            results.append({"kind": "fail" if bad else "pass", "level": "error" if bad else "none",
                            "message": {"text": str(message)}, "locations": [loc]})
        return json.dumps({"version": "2.1.0", "$schema": "https://docs.oasis-open.org/sarif/sarif/v2.1.0/errata01/os/schemas/sarif-schema-2.1.0.json",
                           "runs": [{"tool": {"driver": {"name": "config-file-validator", "informationUri": "https://github.com/Boeing/config-file-validator", "version": "1.8.0"}}, "results": results}]}, indent=2, ensure_ascii=False)
    if kind == "junit":
        failures = sum(_failure(r) for r in records)
        lines = ['<?xml version="1.0" encoding="UTF-8"?>',
                 f' <testsuites name="config-file-validator" tests="{len(records)}">',
                 f'   <testsuite name="config-file-validator" errors="{failures}">']
        for r in records:
            path = html.escape(str(r.get("path", "")), quote=True)
            lines.append(f'     <testcase name="{path} validation" classname="config-file-validator" file="{path}">')
            if _failure(r):
                lines.append('       <failure>')
                for e in r.get("errors") or []:
                    lines.append(f'         <Message>{html.escape(str(e), quote=True)}</Message>')
                lines.extend(['       </failure>', '     </testcase>'])
            else: lines.append('     </testcase>')
        lines.extend(['   </testsuite>', ' </testsuites>'])
        return "\n".join(lines)
    return ""

